static int listener(const string&s){sockaddr_storage a{};socklen_t l;if(!resolve(s,true,a,l))return -1;int fd=socket(a.ss_family,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(fd<0)return -1;int one=1;setsockopt(fd,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));if(bind(fd,(sockaddr*)&a,l)<0||listen(fd,1024)<0){close(fd);return -1;}return fd;}
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<0x80)continue;int n;unsigned int x,min;if(c>=0xc2&&c<=0xdf){n=1;x=c&31;min=0x80;}else if(c>=0xe0&&c<=0xef){n=2;x=c&15;min=0x800;}else if(c>=0xf0&&c<=0xf4){n=3;x=c&7;min=0x10000;}else return false;if(i+n>s.size())return false;for(int j=0;j<n;j++){unsigned char b=s[i++];if((b&0xc0)!=0x80)return false;x=(x<<6)|(b&63);}if(x<min||x>0x10ffff||(x>=0xd800&&x<=0xdfff))return false;}return true;}
static int hex(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static bool decode(const string&s,string&out){out.clear();for(size_t i=0;i<s.size();i++){unsigned char c=s[i];if(c=='%'){if(i+2>=s.size())return false;int a=hex(s[i+1]),b=hex(s[i+2]);if(a<0||b<0)return false;c=(a<<4)|b;i+=2;}if(c==0||c=='\\'||c<32||c==127)return false;out.push_back(c);}return utf8(out);}
struct Header{string name,value;};
static bool parsefields(const string&s,vector<Header>&out){size_t p=0;while(p<s.size()){size_t q=s.find("\r\n",p);if(q==string::npos)return false;if(q==p){return q+2==s.size();}string l=s.substr(p,q-p);size_t c=l.find(':');if(c==string::npos||c==0)return false;for(size_t i=0;i<c;i++)if(!tokenchar((unsigned char)l[i]))return false;for(size_t i=c+1;i<l.size();i++){unsigned char v=l[i];if((v<32&&v!='\t')||v==127)return false;}out.push_back({lower(l.substr(0,c)),trim(l.substr(c+1))});p=q+2;}return false;}
static bool has_token(const string&s,const string&want){size_t p=0;while(p<=s.size()){size_t q=s.find(',',p);if(q==string::npos)q=s.size();if(lower(trim(s.substr(p,q-p)))==want)return true;if(q==s.size())break;p=q+1;}return false;}
static int openfile(int root,const string&path,long long&size){vector<string> parts;size_t p=0;while(p<path.size()){while(p<path.size()&&path[p]=='/')p++;size_t q=p;while(q<path.size()&&path[q]!='/')q++;if(q>p){string v=path.substr(p,q-p);if(v=="..")return -403;if(v!=".")parts.push_back(v);}p=q;}if(parts.empty())return -403;int dir=dup(root);if(dir<0)return -403;for(size_t i=0;i<parts.size();i++){struct stat st{};if(fstatat(dir,parts[i].c_str(),&st,AT_SYMLINK_NOFOLLOW)<0){int e=errno;close(dir);return -(e==ENOENT||e==ENOTDIR?404:403);}if(S_ISLNK(st.st_mode)){close(dir);return -403;}bool last=i+1==parts.size();if(!last&&!S_ISDIR(st.st_mode)){close(dir);return -403;}if(last&&!S_ISREG(st.st_mode)){close(dir);return -403;}int fd=openat(dir,parts[i].c_str(),O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK|(last?0:O_DIRECTORY));if(fd<0){int e=errno;close(dir);return -(e==ENOENT||e==ENOTDIR?404:403);}close(dir);dir=fd;if(last){if(fstat(fd,&st)<0||!S_ISREG(st.st_mode)){close(fd);return -403;}if(!path.empty()&&path.back()=='/'){close(fd);return -403;}size=st.st_size;return fd;}}close(dir);return -403;}
static const char*reason(int s){switch(s){case 200:return "OK";case 400:return "Bad Request";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 431:return "Request Header Fields Too Large";case 502:return "Bad Gateway";default:return "Error";}}
static volatile sig_atomic_t reloadflag=0;static void hup(int){reloadflag=1;}
struct Client {int fd=-1,ufd=-1,file=-1;uint64_t ct=0,ut=0;shared_ptr<Config> cfg,upcfg;SSL*ssl=nullptr;string in,out,upreq,uphead;size_t outpos=0,uppos=0;long long fileleft=0,upremain=0;int requests=0;bool closing=false,head=false,upheaders=false,upcanreuse=false,upretried=false,upreused=false,down_started=false;int state=0,us=0;uint32_t uwant=0;long long idleat=0,headerat=0,writeat=0,upat=0;~Client(){if(ssl)SSL_free(ssl);if(ufd>=0)close(ufd);if(file>=0)close(file);if(fd>=0)close(fd);}};
struct Ref{Client*c;bool upstream;};
static int ep;static uint64_t nexttoken=2;static unordered_map<uint64_t,Ref> refs;static unordered_map<int,unique_ptr<Client>> clients;static shared_ptr<Config> config;static int lfd=-1;static string configpath;
static bool addfd(int fd,uint64_t t,uint32_t events){epoll_event e{};e.events=events;e.data.u64=t;return epoll_ctl(ep,EPOLL_CTL_ADD,fd,&e)==0;}
static void modfd(int fd,uint64_t t,uint32_t events){epoll_event e{};e.events=events|EPOLLRDHUP;e.data.u64=t;epoll_ctl(ep,EPOLL_CTL_MOD,fd,&e);}
