static void killclient(Client*c){int fd=c->fd;dropup(c);epoll_ctl(ep,EPOLL_CTL_DEL,fd,nullptr);refs.erase(c->ct);clients.erase(fd);}
static void interests(Client*c){uint32_t ce=EPOLLRDHUP;if(c->state==0)ce|=EPOLLIN;if(c->state==1&&(c->outpos<c->out.size()||c->fileleft>0))ce|=EPOLLOUT;modfd(c->fd,c->ct,ce);if(c->ufd>=0){uint32_t ue=EPOLLRDHUP;if(c->us==5)ue|=EPOLLIN;else if(c->us!=4||!c->upheaders||c->out.size()-c->outpos<65536)ue|=c->uwant;modfd(c->ufd,c->ut,ue);}}
