static void errorresp(Client*c,int status,bool closeit){if(!c->cfg)c->cfg=config;dropup(c);if(c->file>=0){close(c->file);c->file=-1;c->fileleft=0;}response(c,status,0,closeit);}
static bool openup(Client*c);
