static bool readclient(Client*c){char buf[16384];while(c->state==0){size_t cap=(size_t)config->hbytes+1;if(c->in.size()>=cap){errorresp(c,431,true);return true;}size_t want=min(sizeof(buf),cap-c->in.size());ssize_t n=recv(c->fd,buf,want,0);if(n==0)return false;if(n<0){if(errno==EAGAIN||errno==EWOULDBLOCK)return true;if(errno==EINTR)continue;return false;}long long t=nowms();if(c->in.empty())c->headerat=t;c->idleat=t;c->in.append(buf,n);size_t end=c->in.find("\r\n\r\n");size_t scan=end==string::npos?c->in.size():end+4;for(size_t i=0;i<scan;i++){unsigned char ch=c->in[i];if(ch==0||(ch=='\n'&&(i==0||c->in[i-1]!='\r'))||(ch=='\r'&&i+1<scan&&c->in[i+1]!='\n')){errorresp(c,400,true);return true;}}if(end!=string::npos){if(end+4>(size_t)config->hbytes){errorresp(c,431,true);return true;}string req=c->in.substr(0,end+4);c->in.erase(0,end+4);request(c,req);return true;}if(c->in.size()>=(size_t)config->hbytes){errorresp(c,431,true);return true;}}return true;}
static bool nextrequest(Client*c){if(c->closing)return false;c->state=0;c->out.clear();c->outpos=0;c->cfg.reset();c->idleat=nowms();if(c->in.empty()){c->headerat=0;return true;}c->headerat=nowms();size_t end=c->in.find("\r\n\r\n");size_t scan=end==string::npos?c->in.size():end+4;for(size_t i=0;i<scan;i++)if(c->in[i]==0||(c->in[i]=='\n'&&(i==0||c->in[i-1]!='\r'))||(c->in[i]=='\r'&&i+1<scan&&c->in[i+1]!='\n')){errorresp(c,400,true);return true;}if(end!=string::npos){if(end+4>(size_t)config->hbytes){errorresp(c,431,true);return true;}string s=c->in.substr(0,end+4);c->in.erase(0,end+4);request(c,s);}else if(c->in.size()>=(size_t)config->hbytes)errorresp(c,431,true);return true;}
static bool flushclient(Client*c){for(int i=0;i<64;i++){if(c->outpos<c->out.size()){ssize_t n=send(c->fd,c->out.data()+c->outpos,c->out.size()-c->outpos,MSG_NOSIGNAL);if(n<0){if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)return true;return false;}if(n==0)return false;c->down_started=true;c->outpos+=n;c->writeat=nowms();if(c->outpos<c->out.size())continue;c->out.clear();c->outpos=0;}if(c->fileleft>0){char b[65536];ssize_t n=read(c->file,b,min<long long>(sizeof(b),c->fileleft));if(n<=0)return false;c->fileleft-=n;c->out.assign(b,n);if(c->fileleft==0){close(c->file);c->file=-1;}continue;}if(c->ufd>=0&&c->us!=5){pumpup(c);if(c->state!=1)return true;if(!c->out.empty())continue;if(c->ufd>=0&&c->us!=5)return true;}if(!nextrequest(c))return false;if(c->state!=1)return true;}return true;}
int main(int argc,char**argv){signal(SIGPIPE,SIG_IGN);struct sigaction sa{};sa.sa_handler=hup;sigemptyset(&sa.sa_mask);sigaction(SIGHUP,&sa,nullptr);if(argc!=3||string(argv[1])!="--config")return 1;configpath=argv[2];OPENSSL_init_ssl(0,nullptr);config=loadconfig(configpath);if(!config)return 1;lfd=listener(config->listen);if(lfd<0)return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0||!addfd(lfd,1,EPOLLIN))return 1;epoll_event events[512];long long last=nowms();for(;;){if(reloadflag){reloadflag=0;auto n=loadconfig(configpath);if(n){if(n->listen!=config->listen){int nl=listener(n->listen);if(nl>=0){epoll_ctl(ep,EPOLL_CTL_DEL,lfd,nullptr);close(lfd);lfd=nl;addfd(lfd,1,EPOLLIN);config=n;}}else config=n;}}int count=epoll_wait(ep,events,512,50);if(count<0){if(errno==EINTR)continue;break;}for(int i=0;i<count;i++){uint64_t t=events[i].data.u64;uint32_t ev=events[i].events;if(t==1){for(int j=0;j<256;j++){int fd=accept4(lfd,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(fd<0){if(errno==EINTR){j--;continue;}break;}if(clients.size()>=(size_t)config->maxconn){close(fd);continue;}auto c=make_unique<Client>();c->fd=fd;c->ct=nexttoken++;c->idleat=nowms();Client*p=c.get();if(!addfd(fd,c->ct,EPOLLIN|EPOLLRDHUP))continue;refs[c->ct]={p,false};clients[fd]=move(c);}continue;}auto it=refs.find(t);if(it==refs.end())continue;Client*c=it->second.c;bool up=it->second.upstream;bool alive=true;if(up){pumpup(c);if(c->state==1)alive=flushclient(c);}else{if(c->state==0&&(ev&EPOLLIN))alive=readclient(c);if(alive&&c->state==1)alive=flushclient(c);if(alive&&(ev&(EPOLLERR|EPOLLHUP))&&c->state==0)alive=false;if(alive&&(ev&EPOLLRDHUP)&&c->state==0&&!(ev&EPOLLIN))alive=false;}if(!alive)killclient(c);else interests(c);}long long t=nowms();if(t-last>=50){last=t;vector<int> dead;for(auto &kv:clients){Client*c=kv.second.get();if(c->state==0){if(!c->in.empty()&&t-c->headerat>=config->htime){errorresp(c,400,true);interests(c);}else if(c->in.empty()&&t-c->idleat>=config->idle)dead.push_back(kv.first);}else if(c->ufd>=0&&c->us!=5&&t-c->upat>=c->cfg->idle){upstreamfail(c);interests(c);}else if(c->state==1&&t-c->writeat>=c->cfg->wtime)dead.push_back(kv.first);}for(int fd:dead){auto it=clients.find(fd);if(it!=clients.end())killclient(it->second.get());}}}return 0;}
